recipes.code:
{
  "inputs": [
    {
      "id": "nsl-client-id",
      "type": "promptString",
      "description": "OAuth client ID for public mode (SDK Credentials from console → Security).",
      "password": true
    },
    {
      "id": "nsl-client-secret",
      "type": "promptString",
      "description": "OAuth client secret for public mode.",
      "password": true
    },
    {
      "id": "nsl-api-key",
      "type": "promptString",
      "description": "NSL API key (nsl_...) for internal mode.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@neuronsearchlab/mcp@0.6.0"
      ],
      "env": {
        "NSL_CLIENT_ID": "${input:nsl-client-id}",
        "NSL_CLIENT_SECRET": "${input:nsl-client-secret}",
        "NSL_PLATFORM_MODE": "<nsl-platform-mode>",
        "NSL_API_KEY": "${input:nsl-api-key}"
      }
    }
  }
}
